using Godot;
using System;
using System.IO;
using System.Linq;
public partial class MigrationScene {
 void BuildUi(){NewHud();}
 void UpdateHud(){ComicHud();}
 VBoxContainer Panel(string title){if(menu!=null){ui.RemoveChild(menu);menu.QueueFree();}paused=true;if(ambience!=null)ambience.StreamPaused=true;Input.MouseMode=Input.MouseModeEnum.Visible;menu=new PanelContainer{Position=new Vector2(160,30),Size=new Vector2(960,650),Theme=comicTheme};ui.AddChild(menu);var margin=new MarginContainer();foreach(string key in new[]{"margin_left","margin_top","margin_right","margin_bottom"})margin.AddThemeConstantOverride(key,18);menu.AddChild(margin);var box=new VBoxContainer();box.AddThemeConstantOverride("separation",9);margin.AddChild(box);var heading=new Label{Text=title};heading.AddThemeFontSizeOverride("font_size",23);heading.AddThemeColorOverride("font_color",new Color(.88f,.75f,.48f));box.AddChild(heading);box.AddChild(new HSeparator());return box;}
 void Text(VBoxContainer box,string text){box.AddChild(new Label{Text=text,AutowrapMode=TextServer.AutowrapMode.WordSmart,CustomMinimumSize=new Vector2(880,0)});}
 void Button(VBoxContainer box,string title,Action action){var button=new Godot.Button{Text=title,MouseDefaultCursorShape=Control.CursorShape.PointingHand};box.AddChild(button);button.Pressed+=action;}
 void CloseMenu(){if(menu!=null){ui.RemoveChild(menu);menu.QueueFree();menu=null;}paused=false;if(ambience!=null)ambience.StreamPaused=muted;Input.MouseMode=testing?Input.MouseModeEnum.Visible:Input.MouseModeEnum.Captured;}
 void ShowCrafting(){ComicCrafting();}
 void ShowEquipment(){ComicEquipment();}
 void ShowSkills(){var b=Panel("ACTIVITY ATTRIBUTES / DEATH CLEARS PARTIAL XP, RETAINS LEVELS");var skills=new[]{game.Skills.Strength,game.Skills.Agility,game.Skills.Stamina,game.Skills.Marksmanship,game.Skills.Crafting,game.Skills.Survival};string[] names={"STRENGTH / chop trees / hardwood access and fewer swings","AGILITY / sprint / speed +0.5% (cap10%), stamina +2 per level","STAMINA / sprint / stamina +5 per level","MARKSMANSHIP / hits and kills / damage +1% per level","CRAFTING / recipes / advanced gun requirements","SURVIVAL / gather / provisions and +2% recovery (cap40%)"};for(int i=0;i<6;i++)Text(b,names[i]+"\nLEVEL "+skills[i].Level+" / "+(int)(100*skills[i].Xp/skills[i].Need)+"%");Text(b,"Deaths: "+game.Skills.Deaths);Button(b,"BACK",CloseMenu);}
 void ShowCamps(){var b=Panel("SLEEPING BAGS / RESPAWN / TRAVEL");Text(b,"Bag kits "+game.Life.Bags+" / travel needs daylight, no wounds, safe camps, 1 food + 1 water + 25 energy. Ten-minute cooldown.");Button(b,"PLACE BAG HERE",()=>{game.AddBag(player.Position.X,player.Position.Z,CampSafe);SyncCampObjects();ShowCamps();});var sc=new ScrollContainer{CustomMinimumSize=new Vector2(880,270)};b.AddChild(sc);var rows=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};sc.AddChild(rows);foreach(var camp in game.Life.Camps.Where(c=>c.Seed==game.Save.Seed)){var copy=camp;Text(rows,(camp.Id==game.Life.Respawn?"[RESPAWN] ":"")+"Camp "+(int)camp.X+", "+(int)camp.Z);Button(rows,"BIND RESPAWN",()=>{game.Change(()=>game.Life.Respawn=copy.Id);ShowCamps();});Button(rows,"TRAVEL",()=>{game.Save.X=player.Position.X;game.Save.Z=player.Position.Z;if(game.Travel(copy,CampSafe)=="Travelled"){Teleport(game.Save.X,game.Save.Z);ClearEnemies();}ShowCamps();});}Text(b,game.Notice);Button(b,"REST AT CURRENT BAG",()=>{var camp=game.Life.Camps.Find(c=>c.Seed==game.Save.Seed&&ExpeditionGame.Distance(c.X,c.Z,player.Position.X,player.Position.Z)<4);if(camp!=null&&CampSafe(camp)&&!game.Life.Wounds.Exists(w=>!w.Patched)){game.Change(()=>game.Life.Energy=100);game.Notice="Rested";}else game.Notice="Stand at a safe bag and patch bleeding first";ShowCamps();});Button(b,"BACK",CloseMenu);}
 void ShowPause(){var b=Panel("EXPEDITION / PAUSED");Text(b,"Menus pause the world, needs and wound timers. Saves are independent of update folders.\nExisting relay connection probe: F8. Gameplay networking is not yet ported.");Button(b,"RESUME",CloseMenu);Button(b,"SAVE",()=>{game.Persist();ShowPause();});Button(b,"IMPORT OLD EXPEDITION CHARACTER (replaces this character; previous save kept as .bak)",ImportDialog);var seed=new SpinBox{MinValue=1,MaxValue=999999,Value=game.Save.Seed};b.AddChild(seed);Button(b,"OPEN WORLD SEED (keeps character, per-seed builds and world changes)",()=>{ExitDungeon(false);game.Change(()=>{game.Save.Seed=(int)seed.Value;game.Save.X=0;game.Save.Z=12;game.Normalize();});ClearEnemies();ClearChildren(worldRoot);props.Clear();uniqueObjects.Clear();RebuildTerrain();SyncStructures();Teleport(0,12);CloseMenu();});Text(b,game.Notice);Button(b,"QUIT",()=>{game.Persist();GetTree().Quit();});}
 void ImportDialog(){var fd=new FileDialog{FileMode=FileDialog.FileModeEnum.OpenFile,Access=FileDialog.AccessEnum.Filesystem,Title="Select legacy profiles/expedition-loot.json"};fd.Filters=new[]{"*.json ; Expedition character profile"};ui.AddChild(fd);fd.FileSelected+=path=>{try{string worlds=Path.Combine(Path.GetDirectoryName(Path.GetDirectoryName(path)),"worlds");if(game.ImportLegacy(path,worlds)){ExitDungeon(false);ClearEnemies();ClearChildren(worldRoot);props.Clear();uniqueObjects.Clear();RebuildTerrain();SyncStructures();Teleport(0,12);}ShowPause();}catch(Exception ex){game.Notice="Import failed / "+ex.Message;ShowPause();}fd.QueueFree();};fd.Canceled+=()=>fd.QueueFree();fd.PopupCentered(new Vector2I(900,600));}
 void ShowMap(){var b=Panel("SOUTH BLOCK / SEED "+game.Save.Seed);var map=new ExpeditionMapCanvas{World=game.World,PlayerPosition=player.Position,CustomMinimumSize=new Vector2(880,450)};b.AddChild(map);Text(b,"South meadow T1 Ã¢â€ â€™ woodland T2 Ã¢â€ â€™ outskirts T3 Ã¢â€ â€™ south city T4 Ã¢â€ â€™ city depths T5. River crossing closed.");Button(b,"BACK",CloseMenu);}
 void ShowRelay(){var b=Panel("EXISTING TLS RELAY / CONNECTION PROBE");Text(b,"Transport retained on TCP 28747. This tests connectivity only; Expedition world synchronization is not implemented.");var address=new LineEdit{PlaceholderText="Relay address"};var pin=new LineEdit{PlaceholderText="Certificate SHA256 fingerprint"};b.AddChild(address);b.AddChild(pin);Button(b,"CONNECT",()=>{relay?.Dispose();relay=new RelayLink();relay.Connect(new RelayConfig{Address=address.Text.Trim(),CertificateSha256=pin.Text.Trim(),Port=28747});CloseMenu();});Button(b,"BACK",CloseMenu);}
 void ShowLetter(int kind=1){var b=Panel(JournalText.SceneNames[kind]);Text(b,JournalText.SceneNotes[kind]);Button(b,"BACK",CloseMenu);}
 void ShowJournal(){var b=Panel("FRAGMENTS / JOURNAL");Text(b,game.Profile.Journal.Seen.Count+" recovered fragments. Search abandoned locations with F.");var kinds=new System.Collections.Generic.HashSet<int>();foreach(string id in game.Profile.Journal.Seen){int kind;string tail=id.Substring(id.LastIndexOf('/')+1);if(int.TryParse(tail,out kind)&&kind>=0&&kind<6)kinds.Add(kind);else if(id.EndsWith("/letter"))kinds.Add(1);}foreach(int kind in kinds){int copy=kind;Button(b,JournalText.SceneNames[kind],()=>ShowLetter(copy));}Button(b,"BACK",CloseMenu);}
}
internal partial class ExpeditionMapCanvas:Control {
 internal ExpeditionWorld World;internal Vector3 PlayerPosition;
 Vector2 Map(double x,double z){return new Vector2((float)((x+1600)/3200*Size.X),(float)((z+2850)/3200*Size.Y));}
 public override void _Draw(){if(World==null)return;Color[] colors={Colors.Black,new Color(.41f,.49f,.29f),new Color(.18f,.33f,.22f),new Color(.48f,.39f,.26f),new Color(.36f,.38f,.39f)};for(int x=-1600;x<1600;x+=64)for(int z=-2850;z<350;z+=64){Color c=World.IsRiver(x,z)?new Color(.13f,.30f,.43f):!World.Playable(x,z)?new Color(.14f,.16f,.18f):colors[World.Tier(x,z)];DrawRect(new Rect2(Map(x,z),new Vector2(Size.X/50+1,Size.Y/50+1)),c);}for(int z=-2400;z<300;z+=32)DrawLine(Map(World.RouteX(z),z),Map(World.RouteX(z+32),z+32),new Color(.72f,.64f,.43f),2);foreach(var d in ExpeditionDungeon.Nearby(World,0,0))DrawCircle(Map(d.X,d.Z),4,Colors.Orange);DrawCircle(Map(PlayerPosition.X,PlayerPosition.Z),5,Colors.White);}
}
